import React, { useState } from "react";

export default function ContactPage() {
  const [form, setForm] = useState({ name: "", email: "", phone: "", subject: "", message: "" });
  const [submitted, setSubmitted] = useState(false);

  const handleChange = e => setForm({ ...form, [e.target.name]: e.target.value });

  const handleSubmit = e => {
    e.preventDefault();
    // TODO: Send data to backend API endpoint
    setSubmitted(true);
    // Optionally reset form: setForm({ name: "", email: "", phone: "", subject: "", message: "" });
  };

  return (
    <main>
      <section className="contact-hero">
        <h1>Contact AIMERS</h1>
        <p>We're here for you! Use the details below, or fill out our query form — our team will respond promptly.</p>
      </section>

      <section className="contact-container">
        <div className="contact-info">
          <h2>Contact Details</h2>
          <ul>
            <li><i className="fas fa-phone"></i> Main Office: <a href="tel:+919833312345">+91-98333-12345</a></li>
            <li><i className="fas fa-headset"></i> Student Support: <a href="tel:+919561234567">+91-95612-34567</a></li>
            <li><i className="fas fa-envelope"></i> Email: <a href="mailto:support@aimerscoaching.com">support@aimerscoaching.com</a></li>
            <li><i className="fas fa-envelope-open"></i> Admissions: <a href="mailto:admissions@aimerscoaching.com">admissions@aimerscoaching.com</a></li>
            <li><i className="fas fa-map-marker-alt"></i> Address:<br />
                <span className="address-details">
                3rd Floor, Universal Plaza,<br />
                MG Road, Jaipur, Rajasthan, India 302001
                </span>
            </li>
          </ul>
          <div className="contact-social">
            <a href="https://facebook.com/aimerscoaching" aria-label="Facebook"><i className="fab fa-facebook"></i></a>
            <a href="https://twitter.com/aimerscoaching" aria-label="Twitter"><i className="fab fa-x-twitter"></i></a>
            <a href="https://instagram.com/aimerscoaching" aria-label="Instagram"><i className="fab fa-instagram"></i></a>
            <a href="https://youtube.com/AIMERSCoaching" aria-label="YouTube"><i className="fab fa-youtube"></i></a>
          </div>
        </div>

        <div className="contact-form-block">
          <h2>Contact Form</h2>
          {submitted ? (
            <div className="contact-success">Thank you for your query! Our team will get back to you within 24 hours.</div>
          ) : (
            <form className="contact-form" onSubmit={handleSubmit} autoComplete="off">
              <label>
                Name <span className="required">*</span>
                <input
                  type="text"
                  name="name"
                  required
                  value={form.name}
                  onChange={handleChange}
                  placeholder="Your full name"
                  autoComplete="off"
                />
              </label>
              <label>
                Email <span className="required">*</span>
                <input
                  type="email"
                  name="email"
                  required
                  value={form.email}
                  onChange={handleChange}
                  placeholder="you@email.com"
                  autoComplete="off"
                />
              </label>
              <label>
                Phone
                <input
                  type="tel"
                  name="phone"
                  pattern="[0-9+ ]*"
                  value={form.phone}
                  onChange={handleChange}
                  placeholder="(Optional)"
                  autoComplete="off"
                />
              </label>
              <label>
                Subject <span className="required">*</span>
                <input
                  type="text"
                  name="subject"
                  required
                  value={form.subject}
                  onChange={handleChange}
                  placeholder="Query subject"
                  autoComplete="off"
                />
              </label>
              <label>
                Message <span className="required">*</span>
                <textarea
                  name="message"
                  rows="4"
                  required
                  value={form.message}
                  onChange={handleChange}
                  placeholder="How can we help you?"
                ></textarea>
              </label>
              <button type="submit" className="contact-btn">Send Message</button>
            </form>
          )}
        </div>
      </section>
    </main>
  );
}
