import React, { useState, useEffect } from "react";
import axios from "axios";
import VideoModal from "../components/VideoModal";
import { useAuth } from "../contexts/AuthContext";

// Structured Course Data
const courseData = {
  10: {
    Mathematics: [
      {
        topic: "Real Numbers",
        video: "https://www.youtube.com/watch?v=rfscVS0vtbw",
        dpp: "/uploads/dpps/10th/mathematics/real-numbers.pdf"
      },
      {
        topic: "Quadratic Equations",
        video: "https://www.youtube.com/watch?v=tNkz5A8xi0k",
        dpp: "/uploads/dpps/10th/mathematics/quadratic-equations.pdf"
      }
    ],
    Science: [
      {
        topic: "Life Processes",
        video: "https://www.youtube.com/watch?v=VYMdOc_apy0",
        dpp: "/uploads/dpps/10th/science/life-processes.pdf"
      }
    ]
  },
  12: {
    Mathematics: [
      {
        topic: "Differentiation",
        video: "https://youtube.com/watch?v=YNC7W4R5rsU",
        dpp: "/uploads/dpps/12th/mathematics/differentiation.pdf"
      }
    ],
    Science: [
      {
        topic: "Electrostatics",
        video: "https://youtu.be/2n1xRhzWl2k",
        dpp: "/uploads/dpps/12th/science/electrostatics.pdf"
      }
    ]
  }
};

const gradeOptions = Object.keys(courseData);

export default function CoursesPage() {
  const { token, user } = useAuth();
  const [selectedGrade, setSelectedGrade] = useState(null);
  const [selectedSubject, setSelectedSubject] = useState(null);
  const [videoTopics, setVideoTopics] = useState([]);
  const [loading, setLoading] = useState(false);
  const [videoModal, setVideoModal] = useState({
    isOpen: false,
    videoUrl: '',
    videoTitle: ''
  });
  const [completionStatus, setCompletionStatus] = useState({});

  // Set the user's grade as the default selected grade
  useEffect(() => {
    if (user && user.grade) {
      setSelectedGrade(user.grade);
    }
  }, [user]);

  const reset = () => {
    setSelectedGrade(null);
    setSelectedSubject(null);
    setVideoTopics([]);
    setCompletionStatus({});
    setVideoModal({ isOpen: false, videoUrl: '', videoTitle: '' });
  };

  const openVideoModal = (videoUrl, videoTitle) => {
    setVideoModal({
      isOpen: true,
      videoUrl,
      videoTitle
    });
  };

  const closeVideoModal = () => {
    setVideoModal({
      isOpen: false,
      videoUrl: '',
      videoTitle: ''
    });
  };

  // Fetch video topics when subject is selected
  useEffect(() => {
    if (selectedGrade && selectedSubject) {
      fetchVideoTopics();
      fetchCompletionStatus();
    }
  }, [selectedGrade, selectedSubject, token]);

  const fetchVideoTopics = async () => {
    setLoading(true);
    try {
      const response = await axios.get(`http://localhost:5000/api/videos/${selectedGrade}/${selectedSubject.toLowerCase()}`);
      setVideoTopics(response.data.videoTopics || []);
    } catch (error) {
      console.error('Error fetching video topics:', error);
      // Fallback data for testing
      setVideoTopics([
        {
          _id: 'video1',
          topic: 'Introduction to Mathematics',
          url: 'https://www.youtube.com/watch?v=test1',
          createdAt: new Date().toISOString()
        },
        {
          _id: 'video2',
          topic: 'Basic Algebra',
          url: 'https://www.youtube.com/watch?v=test2',
          createdAt: new Date().toISOString()
        },
        {
          _id: 'video3',
          topic: 'Geometry Fundamentals',
          url: 'https://www.youtube.com/watch?v=test3',
          createdAt: new Date().toISOString()
        }
      ]);
    } finally {
      setLoading(false);
    }
  };

  const fetchCompletionStatus = async () => {
    if (!token) {
      console.log('No token available, using fallback data');
      setCompletionStatus({
        'video1': true,
        'video2': false,
        'video3': true
      });
      return;
    }
    
    try {
      const response = await axios.get(
        `http://localhost:5000/api/dashboard/completion-status/${selectedGrade}/${selectedSubject.toLowerCase()}`,
        {
          headers: { Authorization: `Bearer ${token}` }
        }
      );
      setCompletionStatus(response.data.completionStatus || {});
    } catch (error) {
      console.error('Error fetching completion status:', error);
      // Fallback data for testing
      setCompletionStatus({
        'video1': true,
        'video2': false,
        'video3': true
      });
    }
  };

  const handleCompletionToggle = async (topicId, isCompleted) => {
    console.log('Toggling completion for:', topicId, 'to:', isCompleted);
    
    // For testing, update local state immediately
    setCompletionStatus(prev => ({
      ...prev,
      [topicId]: isCompleted
    }));

    if (!token) {
      console.log('No token available, skipping API call');
      return;
    }

    try {
      await axios.post(
        'http://localhost:5000/api/dashboard/track-video',
        {
          videoId: topicId,
          subject: selectedSubject.toLowerCase(),
          watched: isCompleted,
          grade: selectedGrade
        },
        {
          headers: { Authorization: `Bearer ${token}` }
        }
      );
    } catch (error) {
      console.error('Error updating completion status:', error);
    }
  };

  return (
    <main className="courses-page">
      <section className="courses-hero">
        <h1>📘 AIMERS Courses</h1>
        <p>Select your class and subject to explore topics, download DPP PDFs, and watch lectures.</p>
      </section>

      {/* Step 1: Grade Selection - Only show if user doesn't have a grade set */}
      {!selectedGrade && !user?.grade && (
        <div className="grade-selector">
          {gradeOptions.map((grade) => (
            <button
              key={grade}
              onClick={() => setSelectedGrade(grade)}
              className="grade-btn"
            >
              Grade {grade}
            </button>
          ))}
        </div>
      )}

      {/* Show user's grade info if available */}
      {user?.grade && (
        <div style={{ textAlign: "center", padding: "20px", backgroundColor: "#f8f9fa", borderRadius: "8px", margin: "20px" }}>
          <h3 style={{ color: "#004aad", marginBottom: "10px" }}>
            Welcome, {user.name}! 👋
          </h3>
          <p style={{ color: "#5c6f91", fontSize: "1.1em" }}>
            You're registered for <strong>Grade {user.grade}</strong>
            {user.school && ` from ${user.school}`}
          </p>
        </div>
      )}

      {/* Step 2: Subject Selection */}
      {selectedGrade && !selectedSubject && (
        <>
          <h2 className="step-heading">Subjects for Grade {selectedGrade}</h2>
          <div className="subject-selector">
            {Object.keys(courseData[selectedGrade]).map((subject) => (
              <button
                key={subject}
                onClick={() => setSelectedSubject(subject)}
                className="subject-btn"
              >
                {subject}
              </button>
            ))}
          </div>
          {!user?.grade && (
            <div className="nav-links">
              <button onClick={reset} className="link-btn">← Back to Grades</button>
            </div>
          )}
        </>
      )}

      {/* Step 3: Topic Table */}
      {selectedGrade && selectedSubject && (
        <>
          <h2 className="step-heading">{selectedSubject} – Topics for Grade {selectedGrade}</h2>

          {loading ? (
            <div className="loading-message">
              <p>Loading video topics...</p>
            </div>
          ) : videoTopics.length > 0 ? (
            <table className="topics-table">
              <thead>
                <tr>
                  <th>📄 Topic</th>
                  <th>Video Lecture</th>
                  <th>Uploaded</th>
                  <th>Completed</th>
                </tr>
              </thead>
              <tbody>
                {videoTopics.map((videoTopic, idx) => (
                  <tr key={idx} className={completionStatus[videoTopic._id] ? 'completed-row' : ''}>
                    <td>{videoTopic.topic}</td>
                    <td>
                      <button 
                        onClick={() => openVideoModal(videoTopic.url, videoTopic.topic)}
                        className="video-button"
                      >
                        🎥 Watch Video
                      </button>
                    </td>
                    <td>{new Date(videoTopic.createdAt).toLocaleDateString()}</td>
                    <td>
                      <label className="checkbox-container">
                        <input
                          type="checkbox"
                          checked={completionStatus[videoTopic._id] || false}
                          onChange={(e) => handleCompletionToggle(videoTopic._id, e.target.checked)}
                          className="completion-checkbox"
                        />
                        <span className="checkmark"></span>
                      </label>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          ) : (
            <div className="no-content-message">
              <p>No video topics uploaded yet for this subject.</p>
            </div>
          )}

          <div className="nav-links">
            <button onClick={() => setSelectedSubject(null)} className="link-btn">
              ← Back to Subjects
            </button>
          </div>
        </>
      )}

      {/* Video Modal */}
      <VideoModal
        isOpen={videoModal.isOpen}
        onClose={closeVideoModal}
        videoUrl={videoModal.videoUrl}
        videoTitle={videoModal.videoTitle}
      />
    </main>
  );
}

