import React, { useState, useEffect } from "react";
import { useNavigate } from "react-router-dom";
import { useAuth } from "../contexts/AuthContext";
import axios from "axios";

// API base URL
const API_BASE_URL = 'http://localhost:5000/api';

// Available subjects (matching backend folder structure)
const subjectsByClass = {
  "10th": ["Mathematics", "Physics", "Chemistry"],
  "12th": ["Physics", "Chemistry", "Biology", "Mathematics"],
};

// Generate last 20 years
const last20Years = Array.from({ length: 20 }, (_, i) => (2025 - i).toString());

export default function ExploreBoardPapers() {
  const { token, user } = useAuth();
  const [selectedClass, setSelectedClass] = useState(null);
  const [selectedSubject, setSelectedSubject] = useState(null);
  const [paperProgress, setPaperProgress] = useState({});
  const [paperAvailability, setPaperAvailability] = useState({});
  const [loading, setLoading] = useState(false);
  const navigate = useNavigate();

  // Set the user's grade as the default selected class
  useEffect(() => {
    if (user && user.grade) {
      setSelectedClass(`${user.grade}th`);
    }
  }, [user]);

  // Fetch paper progress when subject is selected
  useEffect(() => {
    if (selectedClass && selectedSubject && token) {
      fetchPaperProgress();
      fetchPaperAvailability();
    }
  }, [selectedClass, selectedSubject, token]);

  const fetchPaperProgress = async () => {
    setLoading(true);
    try {
      const response = await axios.get(
        `${API_BASE_URL}/dashboard/paper-progress/${selectedClass}/${selectedSubject.toLowerCase()}`,
        {
          headers: { Authorization: `Bearer ${token}` }
        }
      );
      setPaperProgress(response.data.progress || {});
    } catch (error) {
      console.error('Error fetching paper progress:', error);
      setPaperProgress({});
    } finally {
      setLoading(false);
    }
  };

  const handlePaperCompletion = async (year, isCompleted) => {
    if (!token) return;

    try {
      await axios.post(
        `${API_BASE_URL}/dashboard/track-paper`,
        {
          paperId: `${selectedClass}-${selectedSubject}-${year}`,
          subject: selectedSubject.toLowerCase(),
          completed: isCompleted,
          grade: selectedClass,
          year: year
        },
        {
          headers: { Authorization: `Bearer ${token}` }
        }
      );

      setPaperProgress(prev => ({
        ...prev,
        [year]: isCompleted
      }));
    } catch (error) {
      console.error('Error updating paper completion:', error);
    }
  };

  const getCompletionPercentage = () => {
    if (!paperProgress || Object.keys(paperProgress).length === 0) return 0;
    const completedCount = Object.values(paperProgress).filter(Boolean).length;
    const totalCount = Object.keys(paperProgress).length;
    return totalCount > 0 ? Math.round((completedCount / totalCount) * 100) : 0;
  };

  // Check if paper is available for a specific year
  const isPaperAvailable = async (year) => {
    try {
      const response = await axios.get(
        `${API_BASE_URL}/papers/check/${selectedClass}/${selectedSubject.toLowerCase()}/${year}`
      );
      return response.data.available;
    } catch (error) {
      console.error('Error checking paper availability:', error);
      return false;
    }
  };

  // Fetch paper availability for all years
  const fetchPaperAvailability = async () => {
    if (!selectedClass || !selectedSubject) return;
    
    try {
      const availability = {};
      
      for (const year of last20Years) {
        try {
          const response = await axios.get(
            `${API_BASE_URL}/papers/check/${selectedClass}/${selectedSubject.toLowerCase()}/${year}`
          );
          availability[year] = response.data.available;
        } catch (error) {
          console.error(`Error checking availability for year ${year}:`, error);
          availability[year] = false;
        }
      }
      
      setPaperAvailability(availability);
    } catch (error) {
      console.error('Error fetching paper availability:', error);
    }
  };

  const handleReset = () => {
    setSelectedClass(null);
    setSelectedSubject(null);
    setPaperProgress({});
    setPaperAvailability({});
  };

  return (
    <main className="explore-container">
      <h1 className="explore-title">Explore Board Exam Papers</h1>

      {/* Step 1: Select Class - Only show if user doesn't have a grade set */}
      {!selectedClass && !user?.grade && (
        <div>
          <h2 className="explore-subtitle">Select Your Class</h2>
          <div className="explore-btn-group">
            {["10th", "12th"].map((cls) => (
              <button
                key={cls}
                className="explore-btn"
                onClick={() => {
                  setSelectedClass(cls);
                  setSelectedSubject(null);
                }}
              >
                Class {cls}
              </button>
            ))}
          </div>
        </div>
      )}

      {/* Show user's grade info if available */}
      {user?.grade && (
        <div style={{ textAlign: "center", padding: "20px", backgroundColor: "#f8f9fa", borderRadius: "8px", margin: "20px" }}>
          <h3 style={{ color: "#004aad", marginBottom: "10px" }}>
            Welcome, {user.name}! 👋
          </h3>
          <p style={{ color: "#5c6f91", fontSize: "1.1em" }}>
            You're registered for <strong>Grade {user.grade}</strong>
            {user.school && ` from ${user.school}`}
          </p>
        </div>
      )}

      {/* Step 2: Subject */}
      {selectedClass && !selectedSubject && (
        <div>
          <h2 className="explore-subtitle">Subjects — Class {selectedClass}</h2>
          <div className="change-option-container">
            <button className="change-option-btn" onClick={handleReset}>← Change Class</button>
          </div>
          <div className="explore-btn-group">
            {subjectsByClass[selectedClass].map((subject) => (
              <button
                key={subject}
                className="explore-btn"
                onClick={() => {
                  setSelectedSubject(subject);
                }}
              >
                {subject}
              </button>
            ))}
          </div>
        </div>
      )}

      {/* Step 3: Year List */}
      {selectedClass && selectedSubject && (
        <div>
          <h2 className="explore-subtitle">{selectedSubject} — Class {selectedClass}</h2>
          
          {/* Progress Overview */}
          <div className="progress-overview">
            <div className="progress-stats">
              <span className="progress-text">
                Papers Completed: {Object.values(paperProgress).filter(Boolean).length} / {last20Years.length}
              </span>
            </div>
          </div>

          <div className="change-option-container">
            <button className="change-option-btn" onClick={() => setSelectedSubject(null)}>← Change Subject</button>
          </div>
          
          <ul className="year-list">
            {last20Years.map((year) => {
              const isCompleted = paperProgress[year];
              const isAvailable = paperAvailability[year];
              return (
                <li
                  key={year}
                  className={`year-item ${isCompleted ? 'completed-year' : ''} ${!isAvailable ? 'paper-unavailable' : ''}`}
                  role="button"
                  tabIndex={0}
                  onClick={() => {
                    if (!isAvailable) {
                      alert("Paper for this year is not available yet.");
                      return;
                    }
                    navigate(`/papers/board/${selectedClass}/${selectedSubject}/${year}`);
                  }}
                  onKeyDown={(e) => {
                    if (e.key === "Enter" || e.key === " ") {
                      if (!isAvailable) {
                        alert("Paper for this year is not available yet.");
                        return;
                      }
                      navigate(`/papers/board/${selectedClass}/${selectedSubject}/${year}`);
                    }
                  }}
                >
                  <div className="year-content">
                    <span className="year-text">{year}</span>
                    <label className="checkbox-container" onClick={e => e.stopPropagation()}>
                      <input
                        type="checkbox"
                        checked={isCompleted || false}
                        onChange={e => handlePaperCompletion(year, e.target.checked)}
                        className="completion-checkbox visually-hidden"
                      />
                      <span className="checkmark"></span>
                    </label>
                  </div>
                  {isCompleted && <div className="completion-badge">✅</div>}
                </li>
              );
            })}
          </ul>
        </div>
      )}
    </main>
  );
}
