// src/pages/AuthPage.jsx
import React, { useState, useEffect } from "react";
import { useNavigate } from "react-router-dom";
import axios from "axios";
import "../Theme.css";
import { useAuth } from "../contexts/AuthContext";

export default function AuthPage() {
  // Modes: "user-login", "user-register", "admin-login"
  const [mode, setMode] = useState("user-login");

  const navigate = useNavigate();
  const { login } = useAuth();
  
  // Enhanced form state for registration
  const [form, setForm] = useState({
    name: "",
    email: "",
    password: "",
    confirmPassword: "",
    grade: "",
    phone: "",
    school: "",
    parentName: "",
    parentPhone: "",
    address: ""
  });
  
  const [message, setMessage] = useState("");

  // Reset form when mode changes
  useEffect(() => {
    setMessage("");
    if (mode === "user-register") {
      setForm({
        name: "",
        email: "",
        password: "",
        confirmPassword: "",
        grade: "",
        phone: "",
        school: "",
        parentName: "",
        parentPhone: "",
        address: ""
      });
    } else {
      setForm({
        name: "",
        email: "",
        password: "",
        confirmPassword: "",
        grade: "",
        phone: "",
        school: "",
        parentName: "",
        parentPhone: "",
        address: ""
      });
    }
  }, [mode]);

  const handleChange = (e) => setForm({ ...form, [e.target.name]: e.target.value });

  const validateForm = () => {
    if (mode === "user-register") {
      if (form.password !== form.confirmPassword) {
        setMessage("Passwords do not match");
        return false;
      }
      if (form.password.length < 6) {
        setMessage("Password must be at least 6 characters long");
        return false;
      }
      if (!form.grade) {
        setMessage("Please select your class");
        return false;
      }
    }
    return true;
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    setMessage("");

    if (!validateForm()) return;

    try {
      if (mode === "user-register") {
        // Register user with enhanced data
        const registrationData = {
          name: form.name,
          email: form.email,
          password: form.password,
          grade: parseInt(form.grade),
          phone: form.phone,
          school: form.school,
          parentName: form.parentName,
          parentPhone: form.parentPhone,
          address: form.address,
          role: "student"
        };

        await axios.post("http://localhost:5000/api/auth/register", registrationData);

        // Auto-login after register
        const res = await axios.post("http://localhost:5000/api/auth/login", {
          email: form.email,
          password: form.password,
        });
        login(res.data.token, res.data.user);
        navigate("/");
      } else if (mode === "user-login") {
        // User login only
        const res = await axios.post("http://localhost:5000/api/auth/login", {
          email: form.email,
          password: form.password,
        });
        login(res.data.token, res.data.user);
        navigate("/");
      } else if (mode === "admin-login") {
        // Admin login (adjust API if necessary)
        const res = await axios.post("http://localhost:5000/api/admin/login", {
          email: form.email,
          password: form.password,
        });
        login(res.data.token, res.data.user);
        navigate("/");
      }
    } catch (err) {
      setMessage(err.response?.data?.error || "Something went wrong.");
    }
  };

  return (
    <main className="auth-simple" style={{ 
      maxWidth: mode === "user-register" ? 600 : 400, 
      margin: "40px auto", 
      padding: 24, 
      boxShadow: "0 2px 8px #888", 
      borderRadius: 8 
    }}>
      <h2 style={{ textAlign: "center", marginBottom: "24px" }}>
        {mode === "user-login" && "User Login"}
        {mode === "user-register" && "Student Registration"}
        {mode === "admin-login" && "Admin Login"}
      </h2>

      <form className="auth-form" onSubmit={handleSubmit} autoComplete="off">
        {/* Registration Form Fields */}
        {mode === "user-register" && (
          <>
            <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: "12px" }}>
              <input
                type="text"
                name="name"
                placeholder="Full Name *"
                value={form.name}
                onChange={handleChange}
                required
                autoFocus
              />
              <input
                type="email"
                name="email"
                placeholder="Email Address *"
                value={form.email}
                onChange={handleChange}
                required
              />
            </div>

            <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: "12px" }}>
              <input
                type="password"
                name="password"
                placeholder="Password *"
                value={form.password}
                onChange={handleChange}
                required
              />
              <input
                type="password"
                name="confirmPassword"
                placeholder="Confirm Password *"
                value={form.confirmPassword}
                onChange={handleChange}
                required
              />
            </div>

            <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: "12px" }}>
              <select
                name="grade"
                value={form.grade}
                onChange={handleChange}
                required
                style={{
                  padding: "12px",
                  borderRadius: "6px",
                  border: "1px solid #ddd",
                  fontSize: "16px"
                }}
              >
                <option value="">Select Your Class *</option>
                <option value="9">Class 9</option>
                <option value="10">Class 10</option>
                <option value="11">Class 11</option>
                <option value="12">Class 12</option>
              </select>
              <input
                type="tel"
                name="phone"
                placeholder="Phone Number"
                value={form.phone}
                onChange={handleChange}
              />
            </div>

            <input
              type="text"
              name="school"
              placeholder="School Name"
              value={form.school}
              onChange={handleChange}
            />

            <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: "12px" }}>
              <input
                type="text"
                name="parentName"
                placeholder="Parent/Guardian Name"
                value={form.parentName}
                onChange={handleChange}
              />
              <input
                type="tel"
                name="parentPhone"
                placeholder="Parent/Guardian Phone"
                value={form.parentPhone}
                onChange={handleChange}
              />
            </div>

            <textarea
              name="address"
              placeholder="Address (Optional)"
              value={form.address}
              onChange={handleChange}
              style={{
                padding: "12px",
                borderRadius: "6px",
                border: "1px solid #ddd",
                fontSize: "16px",
                resize: "vertical",
                minHeight: "80px"
              }}
            />
          </>
        )}

        {/* Login Form Fields */}
        {(mode === "user-login" || mode === "admin-login") && (
          <>
            <input
              type="email"
              name="email"
              placeholder="Email"
              value={form.email}
              onChange={handleChange}
              required
              autoFocus
            />
            <input
              type="password"
              name="password"
              placeholder="Password"
              value={form.password}
              onChange={handleChange}
              required
            />
          </>
        )}

        <button 
          type="submit" 
          style={{ 
            width: "100%", 
            padding: "12px", 
            fontSize: "16px", 
            borderRadius: 6, 
            border: "none", 
            backgroundColor: "#22a6f1", 
            color: "#fff", 
            fontWeight: "bold", 
            cursor: "pointer",
            marginTop: "16px"
          }}
        >
          {mode === "user-login" && "Login"}
          {mode === "user-register" && "Register"}
          {mode === "admin-login" && "Admin Login"}
        </button>
      </form>

      {message && (
        <div className="auth-alert" style={{ 
          marginTop: "16px", 
          color: "red", 
          fontWeight: "600", 
          textAlign: "center",
          padding: "8px",
          backgroundColor: "#ffe6e6",
          borderRadius: "4px"
        }}>
          {message}
        </div>
      )}

      <div className="auth-toggle" style={{ marginTop: "24px", textAlign: "center" }}>
        {/* Links and toggles */}
        {mode === "user-login" && (
          <>
            New to AIMERS?{" "}
            <button type="button" className="auth-switch" onClick={() => setMode("user-register")} style={linkButtonStyle}>
              Register
            </button>
            <br />
            Are you an Admin?{" "}
            <button type="button" className="auth-switch" onClick={() => setMode("admin-login")} style={linkButtonStyle}>
              Admin Login
            </button>
          </>
        )}

        {mode === "user-register" && (
          <>
            Already have an account?{" "}
            <button type="button" className="auth-switch" onClick={() => setMode("user-login")} style={linkButtonStyle}>
              Login
            </button>
            <br />
            Are you an Admin?{" "}
            <button type="button" className="auth-switch" onClick={() => setMode("admin-login")} style={linkButtonStyle}>
              Admin Login
            </button>
          </>
        )}

        {mode === "admin-login" && (
          <>
            Not an Admin?{" "}
            <button type="button" className="auth-switch" onClick={() => setMode("user-login")} style={linkButtonStyle}>
              User Login/Register
            </button>
          </>
        )}
      </div>
    </main>
  );
}

const linkButtonStyle = {
  background: "none",
  border: "none",
  padding: 0,
  color: "#22a6f1",
  cursor: "pointer",
  textDecoration: "underline",
  fontWeight: "600",
  fontSize: "1em",
};
