import { useParams, useNavigate } from "react-router-dom";
import { useEffect, useState, useRef } from "react";
import PDFViewer from "../components/PDFViewer";

export default function PaperViewPage() {
  const { class: paperClass, subject, year } = useParams();
  const navigate = useNavigate();

  // Fix the subject folder name - convert to lowercase and handle spaces properly
  const subjectFolder = subject?.toLowerCase().replace(/\s+/g, "");
  const fileUrl = `http://localhost:5000/uploads/papers/${paperClass}/${subjectFolder}/${year}.pdf`;

  const containerRef = useRef(null);
  const [fileExists, setFileExists] = useState(null); // null=loading, true=exists, false=missing
  const [error, setError] = useState(null);

  // Check if PDF exists before loading
  useEffect(() => {
    setFileExists(null);
    setError(null);
    
    console.log('Checking file URL:', fileUrl);
    
    fetch(fileUrl, { 
      method: "HEAD",
      mode: 'cors'
    })
      .then((res) => {
        console.log('PDF check response:', res.status, res.headers);
        if (res.ok) {
          setFileExists(true);
        } else {
          setFileExists(false);
          setError(`File not found (Status: ${res.status})`);
        }
      })
      .catch((error) => {
        console.error('PDF check error:', error);
        setFileExists(false);
        setError(`Network error: ${error.message}`);
      });
  }, [fileUrl]);

  // Disable right click and keyboard shortcuts
  useEffect(() => {
    const handleContextMenu = (e) => e.preventDefault();
    const handleKeyDown = (e) => {
      if (
        (e.ctrlKey && (e.key === 'p' || e.key === 's' || e.key === 'u')) ||
        (e.ctrlKey && e.shiftKey && e.key === 'I') ||
        e.key === 'F12' ||
        (e.ctrlKey && e.shiftKey && e.key === 'C') ||
        e.key === 'PrintScreen'
      ) {
        e.preventDefault();
        e.stopPropagation();
        return false;
      }
    };
    document.addEventListener('contextmenu', handleContextMenu);
    document.addEventListener('keydown', handleKeyDown);
    return () => {
      document.removeEventListener('contextmenu', handleContextMenu);
      document.removeEventListener('keydown', handleKeyDown);
    };
  }, []);

  return (
    <main
      style={{
        height: "100vh",
        display: "flex",
        flexDirection: "column",
        background: "#f5f8ff",
        padding: "16px 24px",
        overflow: "hidden",
        fontFamily: "'Segoe UI', Tahoma, Geneva, Verdana, sans-serif",
        userSelect: "none",
        WebkitUserSelect: "none",
        MozUserSelect: "none",
        msUserSelect: "none",
        WebkitTouchCallout: "none",
        WebkitTapHighlightColor: "transparent",
      }}
      ref={containerRef}
    >
      {/* Header: Back Button + Heading */}
      <div
        style={{
          display: "flex",
          flexWrap: "wrap",
          justifyContent: "space-between",
          alignItems: "center",
          marginBottom: 12,
          gap: "12px",
        }}
      >
        <button
          onClick={() => navigate(-1)}
          style={{
            padding: "8px 16px",
            backgroundColor: "#fff",
            border: "2px solid #004aad",
            color: "#004aad",
            fontWeight: 700,
            borderRadius: 8,
            cursor: "pointer",
            userSelect: "none",
          }}
        >
          ← Back to Explore
        </button>

        <h2
          style={{
            flex: "1 1 auto",
            color: "#004aad",
            fontWeight: "900",
            fontSize: "1.3rem",
            whiteSpace: "nowrap",
            margin: 0,
            textAlign: "center",
          }}
          title={`${subject} Board Paper – Class ${paperClass}, ${year}`}
        >
          {subject} Board Paper – Class {paperClass}, {year}
        </h2>
      </div>

      {/* PDF Container */}
      <div
        style={{
          flex: 1,
          backgroundColor: "#fff",
          boxShadow: "0 4px 20px rgba(0,0,0,0.1)",
          borderRadius: 12,
          padding: "24px 16px 16px 16px",
          overflow: "auto",
          display: "flex",
          justifyContent: "center",
          alignItems: "flex-start",
          minHeight: 400,
        }}
      >
        {/* Loading message */}
        {fileExists === null && (
          <div style={{ color: "#777", fontSize: "1.1em", margin: "auto" }}>
            🔄 Checking if paper is available...
          </div>
        )}

        {/* File not found message */}
        {fileExists === false && (
          <div
            style={{
              color: "#d32f2f",
              fontWeight: "700",
              fontSize: "1.2em",
              textAlign: "center",
              margin: "auto",
              maxWidth: "600px",
            }}
          >
            ❌ Paper not found for <strong>{subject}</strong> – Class {paperClass}, {year}
            {error && (
              <div style={{ fontSize: "0.9em", marginTop: "10px", color: "#666" }}>
                Error: {error}
              </div>
            )}
            <div style={{ fontSize: "0.9em", marginTop: "10px", color: "#666" }}>
              Expected path: {fileUrl}
            </div>
          </div>
        )}

        {/* PDF Viewer */}
        {fileExists === true && (
          <PDFViewer 
            fileUrl={fileUrl} 
            title={`${subject} Board Paper – Class ${paperClass}, ${year}`}
          />
        )}
      </div>
    </main>
  );
}
