import React, { useState, useEffect } from "react";
import Calendar from "react-calendar";
import { format } from "date-fns";
import { useNavigate } from "react-router-dom";
import { useAuth } from "../contexts/AuthContext";
import axios from "axios";
import "react-calendar/dist/Calendar.css";
import "../Theme.css";

// API base URL
const API_BASE_URL = 'http://localhost:5000/api';

const dppSubjects = [
  {
    subject: "Mathematics",
    description:
      "Algebra, Geometry, Calculus, and more—daily problem sets for each chapter with solutions.",
    icon: "fas fa-calculator",
    color: "#22a6f1",
  },
  {
    subject: "Physics",
    description:
      "Mechanics, Thermodynamics, Optics—daily practice problems for physics concepts and numericals.",
    icon: "fas fa-atom",
    color: "#7df9ed",
  },
  {
    subject: "Chemistry",
    description:
      "Organic, Inorganic, Physical Chemistry—chapter-wise DPPs for chemical concepts and reactions.",
    icon: "fas fa-flask",
    color: "#ff6b35",
  },
  {
    subject: "Biology",
    description:
      "Botany, Zoology, Human Physiology—daily practice for biological concepts and diagrams.",
    icon: "fas fa-dna",
    color: "#00c897",
  },
];

const CLASS_OPTIONS = [9, 10, 11, 12];

export default function DPPPage() {
  const { token, user } = useAuth();
  const [selectedClass, setSelectedClass] = useState(null);
  const [selectedSubject, setSelectedSubject] = useState(null);
  const [dppProgress, setDppProgress] = useState({});
  const [loading, setLoading] = useState(false);
  const [dppAvailability, setDppAvailability] = useState({});
  const navigate = useNavigate();

  // Set the user's grade as the default selected class
  useEffect(() => {
    if (user && user.grade) {
      setSelectedClass(user.grade);
    }
  }, [user]);

  // Fetch DPP progress when subject is selected
  useEffect(() => {
    if (selectedClass && selectedSubject && token) {
      fetchDppProgress();
      fetchDppAvailability();
    }
  }, [selectedClass, selectedSubject, token]);

  const fetchDppProgress = async () => {
    setLoading(true);
    try {
      const response = await axios.get(
        `${API_BASE_URL}/dashboard/dpp-progress/${selectedClass}/${selectedSubject.toLowerCase()}`,
        {
          headers: { Authorization: `Bearer ${token}` }
        }
      );
      setDppProgress(response.data.progress || {});
    } catch (error) {
      console.error('Error fetching DPP progress:', error);
      setDppProgress({});
    } finally {
      setLoading(false);
    }
  };

  // Check if DPP is available for a specific date
  const isDppAvailable = async (date) => {
    try {
      // First check database DPP
      const response = await axios.get(
        `${API_BASE_URL}/dpps/check/${selectedClass}/${selectedSubject.toLowerCase()}/${date}`
      );
      if (response.data.available) {
        return true;
      }
      
      // If no database DPP, check PDF file
      const possiblePdfUrls = [
        `http://localhost:5000/uploads/dpps/${selectedClass}th/${selectedSubject.toLowerCase()}/${date}.pdf`,
        `http://localhost:5000/uploads/dpps/${selectedClass}th/${selectedSubject.toLowerCase()}/${date.split('-')[0]}.pdf`, // year only
        `http://localhost:5000/uploads/dpps/${selectedClass}th/${selectedSubject.toLowerCase()}/${date.replace(/-/g, '')}.pdf`, // no dashes
        `http://localhost:5000/uploads/dpps/${selectedClass}th/${selectedSubject.toLowerCase()}/2023.pdf`, // existing file
        `http://localhost:5000/uploads/dpps/${selectedClass}th/${selectedSubject.toLowerCase()}/2024.pdf`, // other years
        `http://localhost:5000/uploads/dpps/${selectedClass}th/${selectedSubject.toLowerCase()}/2025.pdf`
      ];
      
      for (const pdfUrl of possiblePdfUrls) {
        try {
          const pdfResponse = await fetch(pdfUrl, { method: 'HEAD' });
          if (pdfResponse.ok) {
            return true;
          }
        } catch (pdfError) {
          // Continue to next URL
        }
      }
      
      return false;
    } catch (error) {
      console.error('Error checking DPP availability:', error);
      return false;
    }
  };

  // Fetch DPP availability for the current month
  const fetchDppAvailability = async () => {
    if (!selectedClass || !selectedSubject) return;
    
    try {
      const today = new Date();
      const startOfMonth = new Date(today.getFullYear(), today.getMonth(), 1);
      const endOfMonth = new Date(today.getFullYear(), today.getMonth() + 1, 0);
      
      const availability = {};
      
      for (let d = new Date(startOfMonth); d <= endOfMonth; d.setDate(d.getDate() + 1)) {
        const dateStr = format(d, "yyyy-MM-dd");
        try {
          // First check database DPP
          const response = await axios.get(
            `${API_BASE_URL}/dpps/check/${selectedClass}/${selectedSubject.toLowerCase()}/${dateStr}`
          );
          if (response.data.available) {
            availability[dateStr] = true;
            continue;
          }
          
          // If no database DPP, check PDF file
          const possiblePdfUrls = [
            `http://localhost:5000/uploads/dpps/${selectedClass}th/${selectedSubject.toLowerCase()}/${dateStr}.pdf`,
            `http://localhost:5000/uploads/dpps/${selectedClass}th/${selectedSubject.toLowerCase()}/${dateStr.split('-')[0]}.pdf`, // year only
            `http://localhost:5000/uploads/dpps/${selectedClass}th/${selectedSubject.toLowerCase()}/${dateStr.replace(/-/g, '')}.pdf`, // no dashes
            `http://localhost:5000/uploads/dpps/${selectedClass}th/${selectedSubject.toLowerCase()}/2023.pdf`, // existing file
            `http://localhost:5000/uploads/dpps/${selectedClass}th/${selectedSubject.toLowerCase()}/2024.pdf`, // other years
            `http://localhost:5000/uploads/dpps/${selectedClass}th/${selectedSubject.toLowerCase()}/2025.pdf`
          ];
          
          for (const pdfUrl of possiblePdfUrls) {
            try {
              const pdfResponse = await fetch(pdfUrl, { method: 'HEAD' });
              if (pdfResponse.ok) {
                availability[dateStr] = true;
                break;
              }
            } catch (pdfError) {
              // Continue to next URL
            }
          }
          
          if (!availability[dateStr]) {
            availability[dateStr] = false;
          }
        } catch (error) {
          console.error(`Error checking DPP availability for ${dateStr}:`, error);
          availability[dateStr] = false;
        }
      }
      
      setDppAvailability(availability);
    } catch (error) {
      console.error('Error fetching DPP availability:', error);
    }
  };

  // Navigate to DPP view page on date click
  const handleDateClick = (date) => {
    const formattedDate = format(date, "yyyy-MM-dd");
    
    if (!dppAvailability[formattedDate]) {
      alert("DPP for this date is not available yet.");
      return;
    }
    
    // Use the subject name as is (just lowercase) to match backend expectations
    const subjectParam = selectedSubject.toLowerCase();
    navigate(`/dpps/view/${selectedClass}/${subjectParam}/${formattedDate}`);
  };

  const handleDppCompletion = async (date, isCompleted) => {
    if (!token) return;

    try {
      await axios.post(
        `${API_BASE_URL}/dashboard/track-dpp`,
        {
          dppId: `${selectedClass}-${selectedSubject}-${date}`,
          subject: selectedSubject.toLowerCase(),
          completed: isCompleted,
          grade: selectedClass,
          date: date
        },
        {
          headers: { Authorization: `Bearer ${token}` }
        }
      );

      setDppProgress(prev => ({
        ...prev,
        [date]: isCompleted
      }));
    } catch (error) {
      console.error('Error updating DPP completion:', error);
    }
  };

  const getCompletionPercentage = () => {
    if (!dppProgress || Object.keys(dppProgress).length === 0) return 0;
    const completedCount = Object.values(dppProgress).filter(Boolean).length;
    const totalCount = Object.keys(dppProgress).length;
    return totalCount > 0 ? Math.round((completedCount / totalCount) * 100) : 0;
  };

  const resetView = () => {
    setSelectedSubject(null);
    setSelectedClass(null);
    setDppProgress({});
  };

  const resetToSubjects = () => {
    setSelectedSubject(null);
    setDppProgress({});
  };

  // Custom tile content for calendar
  const tileContent = ({ date, view }) => {
    if (view !== 'month') return null;
    
    const dateStr = format(date, "yyyy-MM-dd");
    const isCompleted = dppProgress[dateStr];
    const isAvailable = dppAvailability[dateStr];
    
    return (
      <div className="calendar-tile-content">
        {isAvailable ? (
          <input
            type="checkbox"
            checked={isCompleted || false}
            onChange={(e) => handleDppCompletion(dateStr, e.target.checked)}
            className="dpp-checkbox"
            style={{
              width: '16px',
              height: '16px',
              cursor: 'pointer',
              margin: '2px'
            }}
          />
        ) : (
          <div 
            className="dpp-unavailable"
            style={{
              width: '16px',
              height: '16px',
              backgroundColor: '#f3f4f6',
              border: '1px solid #d1d5db',
              borderRadius: '4px',
              margin: '2px',
              cursor: 'not-allowed'
            }}
            title="DPP not available yet"
          />
        )}
      </div>
    );
  };

  return (
    <main>
      {/* Hero Section */}
      <section className="dpp-hero">
        <h1>Daily Practice Problems (DPPs)</h1>
        <p style={{ maxWidth: 540, margin: "0 auto" }}>
          Solve new chapter-wise problems every day to strengthen understanding
          and build exam confidence. Choose your subject below to begin.
        </p>
      </section>

      {/* Class Selection - Only show if user doesn't have a grade set */}
      {!selectedClass && !user?.grade && (
        <section style={{ textAlign: "center", padding: "40px 20px" }}>
          <h2 className="explore-subtitle">Select Your Class</h2>
          <p style={{ color: "#5c6f91", fontSize: "1.1em", marginBottom: "40px", maxWidth: "600px", margin: "0 auto 40px auto" }}>
            Choose your grade level to access the appropriate DPPs and practice materials.
          </p>
          <div style={{ display: "flex", justifyContent: "center", gap: "24px", flexWrap: "wrap" }}>
            {CLASS_OPTIONS.map((classNum) => (
              <button
                key={classNum}
                className="dpp-btn class-select"
                onClick={() => setSelectedClass(classNum)}
              >
                Grade {classNum}
              </button>
            ))}
          </div>
        </section>
      )}

      {/* Show user's grade info if available */}
      {user?.grade && (
        <section style={{ textAlign: "center", padding: "20px", backgroundColor: "#f8f9fa", borderRadius: "8px", margin: "20px" }}>
          <h3 style={{ color: "#004aad", marginBottom: "10px" }}>
            Welcome, {user.name}! 👋
          </h3>
          <p style={{ color: "#5c6f91", fontSize: "1.1em" }}>
            You're registered for <strong>Grade {user.grade}</strong>
            {user.school && ` from ${user.school}`}
          </p>
        </section>
      )}

      {/* Subject List */}
      {selectedClass && !selectedSubject && (
        <section style={{ padding: "40px 20px" }}>
          <div style={{ textAlign: "center", marginBottom: "40px" }}>
            <h2 className="explore-subtitle">Subjects for Grade {selectedClass}</h2>
            <p style={{ color: "#5c6f91", fontSize: "1.1em", maxWidth: "600px", margin: "0 auto" }}>
              Select a subject to view and access daily practice problems for Grade {selectedClass}.
            </p>
          </div>
          {!user?.grade && (
            <div className="change-option-container" style={{ textAlign: "center", marginBottom: "30px" }}>
              <button className="change-option-btn" onClick={resetView}>
                ← Go Back to Classes
              </button>
            </div>
          )}
          <div className="dpp-grid">
            {dppSubjects.map(({ subject, description, icon, color }) => (
              <div
                className="dpp-card"
                key={subject}
                style={{ borderLeft: `7px solid ${color}` }}
              >
                <div
                  className="dpp-icon"
                  style={{ background: `${color}1a`, color: color }}
                >
                  <i className={icon}></i>
                </div>
                <div className="dpp-content">
                  <div className="dpp-title">{subject}</div>
                  <div className="dpp-desc">{description}</div>
                  <button
                    className="dpp-btn"
                    onClick={() => setSelectedSubject(subject)}
                  >
                    Open {subject} Calendar
                  </button>
                </div>
              </div>
            ))}
          </div>
        </section>
      )}

      {/* Calendar */}
      {selectedSubject && (
        <section style={{ textAlign: "center", marginTop: 40 }}>
          <h2 className="explore-subtitle">DPP Calendar — Grade {selectedClass} {selectedSubject}</h2>
          
          {/* Progress Overview */}
          <div className="progress-overview">
            <div className="progress-stats">
              <span className="progress-text">Overall Progress: {getCompletionPercentage()}%</span>
              <div className="progress-bar">
                <div 
                  className="progress-fill" 
                  style={{ width: `${getCompletionPercentage()}%` }}
                ></div>
              </div>
            </div>
          </div>

          <div className="change-option-container" style={{ marginBottom: "20px" }}>
            <button className="change-option-btn" onClick={resetToSubjects}>
              ← Go Back to Subjects
            </button>
          </div>
          
          <div style={{ display: "flex", justifyContent: "center" }}>
            <Calendar 
              onClickDay={handleDateClick} 
              tileContent={tileContent}
              className="dpp-calendar"
            />
          </div>

          {/* Completion Instructions */}
          <div className="completion-instructions">
            <p>📋 Check the boxes to mark DPPs as completed</p>
            <p>Your progress will be automatically saved to your dashboard</p>
          </div>
        </section>
      )}
    </main>
  );
}
