import React, { useState, useEffect } from "react";
import { useAuth } from "../contexts/AuthContext";
import axios from "axios";
import { Line, Bar, Doughnut } from "react-chartjs-2";
import {
  Chart as ChartJS,
  CategoryScale,
  LinearScale,
  PointElement,
  LineElement,
  BarElement,
  ArcElement,
  Title,
  Tooltip,
  Legend,
} from "chart.js";

// Register Chart.js components
ChartJS.register(
  CategoryScale,
  LinearScale,
  PointElement,
  LineElement,
  BarElement,
  ArcElement,
  Title,
  Tooltip,
  Legend
);

export default function MyAccount() {
  const { token, logout } = useAuth();
  const [user, setUser] = useState(null);
  const [loading, setLoading] = useState(true);
  const [activeTab, setActiveTab] = useState("overview");
  const [dashboardData, setDashboardData] = useState({
    dppProgress: [],
    videoProgress: [],
    studyStreak: 0,
    totalStudyTime: 0,
    subjects: [],
    recentActivity: []
  });

  useEffect(() => {
    fetchUserData();
    fetchDashboardData();
  }, []);

  const fetchUserData = async () => {
    try {
      const response = await axios.get("http://localhost:5000/api/user/profile", {
        headers: { Authorization: `Bearer ${token}` }
      });
      setUser(response.data);
    } catch (error) {
      console.error("Error fetching user data:", error);
    } finally {
      setLoading(false);
    }
  };

  const fetchDashboardData = async () => {
    try {
      const response = await axios.get("http://localhost:5000/api/dashboard", {
        headers: { Authorization: `Bearer ${token}` }
      });
      setDashboardData(response.data);
    } catch (error) {
      console.error("Error fetching dashboard data:", error);
      // Set mock data for development
      setMockDashboardData();
    }
  };

  const setMockDashboardData = () => {
    setDashboardData({
      dppProgress: [
        { subject: "Mathematics", completed: 45, total: 60, percentage: 75 },
        { subject: "Physics", completed: 38, total: 55, percentage: 69 },
        { subject: "Chemistry", completed: 42, total: 58, percentage: 72 },
        { subject: "Biology", completed: 35, total: 50, percentage: 70 }
      ],
      videoProgress: [
        { subject: "Mathematics", watched: 12, total: 20, percentage: 60 },
        { subject: "Physics", watched: 15, total: 18, percentage: 83 },
        { subject: "Chemistry", watched: 10, total: 16, percentage: 62 },
        { subject: "Biology", watched: 8, total: 14, percentage: 57 }
      ],
      studyStreak: 7,
      totalStudyTime: 156,
      subjects: ["Mathematics", "Physics", "Chemistry", "Biology"],
      recentActivity: [
        { type: "dpp", subject: "Mathematics", action: "Completed DPP", time: "2 hours ago" },
        { type: "video", subject: "Physics", action: "Watched lecture", time: "4 hours ago" },
        { type: "dpp", subject: "Chemistry", action: "Started DPP", time: "1 day ago" },
        { type: "video", subject: "Biology", action: "Completed video", time: "2 days ago" }
      ]
    });
  };

  const handleLogout = () => {
    logout();
  };

  if (loading) {
    return (
      <div style={{ 
        display: "flex", 
        justifyContent: "center", 
        alignItems: "center", 
        height: "60vh",
        fontSize: "1.2rem",
        color: "#666"
      }}>
        Loading your dashboard...
      </div>
    );
  }

  // Chart data for performance analytics
  const performanceData = {
    labels: dashboardData.subjects,
    datasets: [
      {
        label: "DPP Completion %",
        data: dashboardData.dppProgress.map(d => d.percentage),
        borderColor: "#3b82f6",
        backgroundColor: "rgba(59, 130, 246, 0.1)",
        tension: 0.4
      },
      {
        label: "Video Progress %",
        data: dashboardData.videoProgress.map(v => v.percentage),
        borderColor: "#10b981",
        backgroundColor: "rgba(16, 185, 129, 0.1)",
        tension: 0.4
      }
    ]
  };

  const streakData = {
    labels: ["Mon", "Tue", "Wed", "Thu", "Fri", "Sat", "Sun"],
    datasets: [{
      label: "Study Hours",
      data: [2, 3, 1, 4, 2, 3, 2],
      backgroundColor: "#3b82f6",
      borderRadius: 4
    }]
  };

  const subjectProgressData = {
    labels: dashboardData.subjects,
    datasets: [{
      data: dashboardData.dppProgress.map(d => d.percentage),
      backgroundColor: [
        "#3b82f6",
        "#10b981", 
        "#f59e0b",
        "#ef4444"
      ],
      borderWidth: 2,
      borderColor: "#fff"
    }]
  };

  return (
    <main className="dashboard-page">
      {/* Header */}
      <section className="dashboard-header">
        <div className="dashboard-welcome">
          <h1>Welcome back, {user?.name || "Student"}! 👋</h1>
          <p>Here's your personalized learning dashboard</p>
        </div>
        <div className="dashboard-stats">
          <div className="stat-card">
            <div className="stat-icon">🔥</div>
            <div className="stat-content">
              <h3>{dashboardData.studyStreak}</h3>
              <p>Day Streak</p>
            </div>
          </div>
          <div className="stat-card">
            <div className="stat-icon">⏱️</div>
            <div className="stat-content">
              <h3>{dashboardData.totalStudyTime}h</h3>
              <p>Total Study Time</p>
            </div>
          </div>
          <div className="stat-card">
            <div className="stat-icon">📚</div>
            <div className="stat-content">
              <h3>{dashboardData.dppProgress.reduce((sum, d) => sum + d.completed, 0)}</h3>
              <p>DPPs Completed</p>
            </div>
          </div>
        </div>
      </section>

      {/* Navigation Tabs */}
      <section className="dashboard-nav">
        <button 
          className={`nav-tab ${activeTab === "overview" ? "active" : ""}`}
          onClick={() => setActiveTab("overview")}
        >
          📊 Overview
        </button>
        <button 
          className={`nav-tab ${activeTab === "progress" ? "active" : ""}`}
          onClick={() => setActiveTab("progress")}
        >
          📈 Progress
        </button>
        <button 
          className={`nav-tab ${activeTab === "analytics" ? "active" : ""}`}
          onClick={() => setActiveTab("analytics")}
        >
          📋 Analytics
        </button>
        <button 
          className={`nav-tab ${activeTab === "activity" ? "active" : ""}`}
          onClick={() => setActiveTab("activity")}
        >
          🕒 Activity
        </button>
        <button 
          className={`nav-tab ${activeTab === "profile" ? "active" : ""}`}
          onClick={() => setActiveTab("profile")}
        >
          👤 Profile
        </button>
      </section>

      {/* Dashboard Content */}
      <section className="dashboard-content">
        {activeTab === "overview" && (
          <div className="overview-grid">
            {/* Performance Overview */}
            <div className="dashboard-card performance-card">
              <h3>Performance Overview</h3>
              <div className="chart-container">
                <Line 
                  data={performanceData}
                  options={{
                    responsive: true,
                    plugins: {
                      legend: { position: "top" },
                      title: { display: false }
                    },
                    scales: {
                      y: { beginAtZero: true, max: 100 }
                    }
                  }}
                />
              </div>
            </div>

            {/* Subject Progress */}
            <div className="dashboard-card progress-card">
              <h3>Subject Progress</h3>
              <div className="chart-container">
                <Doughnut 
                  data={subjectProgressData}
                  options={{
                    responsive: true,
                    plugins: {
                      legend: { position: "bottom" }
                    }
                  }}
                />
              </div>
            </div>

            {/* Study Streak */}
            <div className="dashboard-card streak-card">
              <h3>Weekly Study Pattern</h3>
              <div className="chart-container">
                <Bar 
                  data={streakData}
                  options={{
                    responsive: true,
                    plugins: {
                      legend: { display: false }
                    },
                    scales: {
                      y: { beginAtZero: true }
                    }
                  }}
                />
              </div>
            </div>

            {/* Quick Actions */}
            <div className="dashboard-card actions-card">
              <h3>Quick Actions</h3>
              <div className="quick-actions">
                <button className="action-btn">
                  <span>📝</span>
                  Start Today's DPP
                </button>
                <button className="action-btn">
                  <span>🎥</span>
                  Continue Video
                </button>
                <button className="action-btn">
                  <span>📊</span>
                  View Progress Report
                </button>
                <button className="action-btn">
                  <span>❓</span>
                  Ask Doubt
                </button>
              </div>
            </div>
          </div>
        )}

        {activeTab === "progress" && (
          <div className="progress-grid">
            {/* DPP Progress */}
            <div className="dashboard-card">
              <h3>DPP Completion Progress</h3>
              <div className="progress-list">
                {dashboardData.dppProgress.map((subject, index) => (
                  <div key={index} className="progress-item">
                    <div className="progress-header">
                      <span className="subject-name">{subject.subject}</span>
                      <span className="progress-percentage">{subject.percentage}%</span>
                    </div>
                    <div className="progress-bar">
                      <div 
                        className="progress-fill" 
                        style={{ width: `${subject.percentage}%` }}
                      ></div>
                    </div>
                    <div className="progress-stats">
                      <span>{subject.completed}/{subject.total} DPPs completed</span>
                    </div>
                  </div>
                ))}
              </div>
            </div>

            {/* Video Progress */}
            <div className="dashboard-card">
              <h3>Video Watch Progress</h3>
              <div className="progress-list">
                {dashboardData.videoProgress.map((subject, index) => (
                  <div key={index} className="progress-item">
                    <div className="progress-header">
                      <span className="subject-name">{subject.subject}</span>
                      <span className="progress-percentage">{subject.percentage}%</span>
                    </div>
                    <div className="progress-bar">
                      <div 
                        className="progress-fill video-fill" 
                        style={{ width: `${subject.percentage}%` }}
                      ></div>
                    </div>
                    <div className="progress-stats">
                      <span>{subject.watched}/{subject.total} videos watched</span>
                    </div>
                  </div>
                ))}
              </div>
            </div>
          </div>
        )}

        {activeTab === "analytics" && (
          <div className="analytics-grid">
            {/* Study Analytics */}
            <div className="dashboard-card">
              <h3>Study Analytics</h3>
              <div className="analytics-stats">
                <div className="analytics-item">
                  <div className="analytics-icon">📊</div>
                  <div className="analytics-content">
                    <h4>Average Daily Study Time</h4>
                    <p>2.5 hours</p>
                  </div>
                </div>
                <div className="analytics-item">
                  <div className="analytics-icon">🎯</div>
                  <div className="analytics-content">
                    <h4>Best Performing Subject</h4>
                    <p>Physics (83%)</p>
                  </div>
                </div>
                <div className="analytics-item">
                  <div className="analytics-icon">📈</div>
                  <div className="analytics-content">
                    <h4>Improvement Rate</h4>
                    <p>+15% this month</p>
                  </div>
                </div>
                <div className="analytics-item">
                  <div className="analytics-icon">⏰</div>
                  <div className="analytics-content">
                    <h4>Peak Study Time</h4>
                    <p>6:00 PM - 8:00 PM</p>
                  </div>
                </div>
              </div>
            </div>

            {/* Performance Trends */}
            <div className="dashboard-card">
              <h3>Performance Trends</h3>
              <div className="chart-container">
                <Line 
                  data={performanceData}
                  options={{
                    responsive: true,
                    plugins: {
                      legend: { position: "top" }
                    },
                    scales: {
                      y: { beginAtZero: true, max: 100 }
                    }
                  }}
                />
              </div>
            </div>
          </div>
        )}

        {activeTab === "activity" && (
          <div className="activity-grid">
            <div className="dashboard-card">
              <h3>Recent Activity</h3>
              <div className="activity-list">
                {dashboardData.recentActivity.map((activity, index) => (
                  <div key={index} className="activity-item">
                    <div className="activity-icon">
                      {activity.type === "dpp" ? "📝" : "🎥"}
                    </div>
                    <div className="activity-content">
                      <h4>{activity.action}</h4>
                      <p>{activity.subject} • {activity.time}</p>
                    </div>
                  </div>
                ))}
              </div>
            </div>

            <div className="dashboard-card">
              <h3>Study Streak Calendar</h3>
              <div className="streak-calendar">
                {/* Calendar grid would go here */}
                <div className="calendar-placeholder">
                  <p>📅 Study streak visualization</p>
                  <p>Current streak: {dashboardData.studyStreak} days</p>
                </div>
              </div>
            </div>
          </div>
        )}

        {activeTab === "profile" && (
          <div className="profile-grid">
            <div className="dashboard-card">
              <h3>Profile Information</h3>
              <div className="profile-info">
                <div className="profile-item">
                  <label>Name:</label>
                  <span>{user?.name || "Not set"}</span>
                </div>
                <div className="profile-item">
                  <label>Email:</label>
                  <span>{user?.email || "Not set"}</span>
                </div>
                <div className="profile-item">
                  <label>Grade:</label>
                  <span>Grade {user?.grade || "Not set"}</span>
                </div>
                <div className="profile-item">
                  <label>Role:</label>
                  <span>{user?.role || "Student"}</span>
                </div>
              </div>
            </div>

            <div className="dashboard-card">
              <h3>Account Actions</h3>
              <div className="account-actions">
                <button className="action-btn">Edit Profile</button>
                <button className="action-btn">Change Password</button>
                <button className="action-btn">Download Progress Report</button>
                <button className="action-btn logout-btn" onClick={handleLogout}>
                  Logout
                </button>
              </div>
            </div>
          </div>
        )}
      </section>
    </main>
  );
}
