import React from "react";
import { Link, useLocation } from "react-router-dom";
import { useAuth } from "../contexts/AuthContext";

function AuthButton() {
  const { token } = useAuth();

  return token ? (
    <Link to="/my-account">
      <button className="nav-account-btn">My Account</button>
    </Link>
  ) : (
    <Link to="/auth">
      <button className="nav-login-btn">Login</button>
    </Link>
  );
}

function Header() {
  const location = useLocation();
  const isActive = (path) => location.pathname.startsWith(path);

  return (
    <header className="header">
      <Link to="/" className="logo">AIMERS</Link>
      <nav className="nav">
        <Link to="/" className={isActive("/") ? "active" : ""}>Home</Link>
        <Link to="/courses" className={isActive("/courses") ? "active" : ""}>Courses</Link>
        <Link to="/dpps" className={isActive("/dpps") ? "active" : ""}>DPPs</Link>
        <Link to="/papers" className={isActive("/papers") ? "active" : ""}>Papers</Link>
        <Link to="/about" className={isActive("/about") ? "active" : ""}>About</Link>
        <Link to="/contact" className={isActive("/contact") ? "active" : ""}>Contact</Link>

        {/* ✅ Add Upload Link (Visible to All Now, Optional: Make Conditional If Needed) */}
        <Link to="/upload" className={isActive("/upload") ? "active" : ""}>Upload</Link>

        <AuthButton />
      </nav>
    </header>
  );
}

export default Header;
